    bool attachedRigidFace=false,allRigidFace=false,freeRootFace=false,freeDistalFace=false;for(const auto& p:hair->probes)if(p.triangleSample){attachedRigidFace|=p.triangle==std::array<std::uint32_t,3>{0,1,12};allRigidFace|=p.triangle==std::array<std::uint32_t,3>{12,13,14};freeRootFace|=p.triangle==std::array<std::uint32_t,3>{1,12,6};freeDistalFace|=p.triangle==std::array<std::uint32_t,3>{1,12,7};}
