    bool budget=true;double largestDistal=0;for(auto v:attached){detail::HairAttachmentWeights profile;budget&=detail::AuthoredHairBlend(source,hair->chains[0],0,v,hair->unitsPerMeter,profile);budget&=2*profile.rootLever*std::sin(hair->chains[0].links[0].maxAngle*.5)+profile.distalCapacity<=.0015+1e-12;largestDistal=std::max(largestDistal,profile.distalCapacity);}Expect(budget&&largestDistal>0&&largestDistal<=.0005,"Every attachment reserves all descendant motion capacity before assigning the 1.5 mm total drift budget");
    auto animated=EvaluateSkeletalPose(source,nullptr,0,false);StaticModel original,stressed;bool stress=SkinSkeletalMesh(source,animated,original,&error);double measured=0;for(int sample=0;sample<512&&stress;++sample){auto pose=animated;for(std::size_t j=0;j<hair->chains[0].links.size();++j){const auto& link=hair->chains[0].links[j];const auto axis=glm::normalize(glm::dvec3(std::sin(sample*.73+j+.2),std::cos(sample*.51+j*.7),std::sin(sample*.37+j*1.3+.1)));pose.local[link.bone].rotation=glm::angleAxis(link.maxAngle*((sample&(1<<j))?1.:-1.),axis)*animated.local[link.bone].rotation;}pose.global=GlobalBoneTransforms(source.skeleton,pose.local);stress=SkinSkeletalMesh(source,pose,stressed,&error);for(auto v:attached)measured=std::max(measured,glm::length(stressed.meshes[0].vertices[v].position-original.meshes[0].vertices[v].position)/hair->unitsPerMeter);}
