void SurfaceCoverageTests(){
    std::puts("Position, orientation and skin-weight strata in a fixed probe budget:");auto p=Fixture();p.skeleton.bones[4].name="J_Sec_Hair3_01";p.skeleton.bones[4].parent=3;const auto globals=GlobalBoneTransforms(p.skeleton,RestPose(p.skeleton));for(std::size_t b=0;b<globals.size();++b)p.skeleton.bones[b].inverseBind=glm::inverse(globals[b]);auto& mesh=p.geometry->meshes[0];auto& skin=p.skins[0];mesh.vertices.clear();mesh.indices.clear();mesh.bounds={};skin.vertices.clear();skin.sourceVertexIds.clear();skin.boneFromMesh.clear();for(const auto& b:p.skeleton.bones)skin.boneFromMesh.push_back(b.inverseBind);p.geometry->bounds={};
    constexpr std::uint32_t side=8,perCopy=side*side;for(std::uint32_t copy=0;copy<4;++copy){const auto base=static_cast<std::uint32_t>(mesh.vertices.size());for(std::uint32_t y=0;y<side;++y)for(std::uint32_t x=0;x<side;++x){StaticVertex v;v.position={-.15+.3*double(x)/(side-1),1.55-.85*double(y)/(side-1),.2};v.normal={0,0,copy%2?-1.f:1.f};mesh.vertices.push_back(v);mesh.bounds.Include(v.position);p.geometry->bounds.Include(v.position);VertexSkin w;w.joints={copy<2?3u:4u,0,0,0};skin.vertices.push_back(w);skin.sourceVertexIds.push_back(static_cast<std::uint32_t>(skin.sourceVertexIds.size()));}for(std::uint32_t y=0;y+1<side;++y)for(std::uint32_t x=0;x+1<side;++x){const auto a=base+y*side+x;mesh.indices.insert(mesh.indices.end(),{a,a+1,a+side,a+1,a+side+1,a+side});}}
    p.geometry->bounds.Include({0,0,0});std::string error;HairBuildOptions options;options.maxProbes=64;const auto hair=BuildHairAsset(p,p,options,&error);if(!Expect(bool(hair),"Generate 64 probes for four coincident surfaces with opposite normals and different skin joints"))throw std::runtime_error(error);
    std::set<std::uint32_t> represented;for(const auto& probe:hair->probes)represented.insert((probe.triangleSample?probe.triangle[0]:probe.vertex)/perCopy);Expect(hair->probes.size()==64&&represented==std::set<std::uint32_t>{0,1,2,3},"Both rendered sides of both joint-weight patches receive representatives without increasing the budget");
    Expect(mesh.vertices[0].position==mesh.vertices[perCopy].position&&mesh.vertices[0].position==mesh.vertices[2*perCopy].position&&skin.vertices[0].joints[0]!=skin.vertices[2*perCopy].joints[0]&&mesh.vertices[0].normal==-mesh.vertices[perCopy].normal,"Coverage fixture isolates orientation and skin features at exactly equal source positions");
    Expect(ValidateHairAsset(*hair,p,&error)&&hair->attachments.empty(),"Orientation/skin-aware sampling preserves binding validity and does not turn free surface into an attachment");
}
std::map<fs::path,std::string> BundleBytes(const fs::path& directory){std::map<fs::path,std::string> result;for(const auto& entry:fs::recursive_directory_iterator(directory))if(entry.is_regular_file()){std::ifstream stream(entry.path(),std::ios::binary);result.emplace(entry.path().lexically_relative(directory),std::string(std::istreambuf_iterator<char>(stream),{}));}return result;}
